CREATE TABLE public.service_enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL, business_name text, phone text NOT NULL, whatsapp text, email text NOT NULL, city text, instagram text, website text, service text NOT NULL, package_name text, requirements text NOT NULL, expected_start date, contact_method text, additional_requirements text, budget text, consent boolean NOT NULL DEFAULT false, amount_paise integer, billing text, status text NOT NULL DEFAULT 'enquiry' CHECK (status IN ('enquiry','pending','paid','failed','cancelled')), payu_txnid text UNIQUE, payu_mihpayid text); GRANT ALL ON public.service_enquiries TO service_role; ALTER TABLE public.service_enquiries ENABLE ROW LEVEL SECURITY; CREATE INDEX service_enquiries_created_at_idx ON public.service_enquiries(created_at DESC);